	@Test
	void directServiceLeafCancellationPropagatesAndReleasesTheLease(@TempDir Path directory) throws Exception {
		FrontierStatisticsHeapGovernor governor = FrontierStatisticsHeapGovernor.forBudget(16L * 1024L * 1024L);
		FrontierStatisticsLease generation = mock(FrontierStatisticsLease.class);
		FrontierStatisticsHeapGovernor.Lease scratch = mock(FrontierStatisticsHeapGovernor.Lease.class);
		FrontierLeafProbe probe = new FrontierLeafProbe(FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.PREDICATE,
				0L, 1L, 0L, 0L);
		QueryInterruptedException cancelled = new QueryInterruptedException("cancelled query");
		when(generation.ready()).thenReturn(true);
		when(generation.estimateLeaf(probe)).thenThrow(cancelled);
		try (LmdbStatisticsService service = spy(LmdbStatisticsService.open(directory, governor,
				16L * 1024L * 1024L, 60_000L))) {
			doReturn(scratch).when(service).tryAcquireQueryScratch(64L * 1024L);
			doReturn(generation).when(service).acquire(1L);
			assertSame(cancelled,
					assertThrows(QueryInterruptedException.class, () -> service.estimateLeaf(1L, probe)));
		}
		verify(scratch).close();
		verify(generation).close();
	}

